import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1787084764000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>See the <a href="/reference/environment">environment variable reference</a> for the full table.</p><h2 id="getting-a-token" tabindex="-1">Getting a token <a class="header-anchor" href="#getting-a-token" aria-label="Permalink to “Getting a token”">​</a></h2><p>Create the token in Mealie under <strong>Settings → API Tokens</strong>. The token acts as the user who created it and inherits that user&#39;s group, household and permission flags — there are no finer-grained scopes in Mealie.</p><p>Give the server a <strong>dedicated, non-admin user</strong>. The admin-only surface is not exposed by any tool here, but a token minted from an admin account still carries those rights if anything else ever reaches the API with it. A sensible user for this server has <code>canOrganize</code> (needed for tags, categories, foods and units) and neither <code>canManage</code> nor <code>canInvite</code>.</p><p>Once read, the token is deleted from the process environment, so child processes cannot pick it up out of <code>/proc/&lt;pid&gt;/environ</code>.</p><h2 id="required-variables" tabindex="-1">Required variables <a class="header-anchor" href="#required-variables" aria-label="Permalink to “Required variables”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>MEALIE_URL</code></td><td>Base URL of the instance, e.g. <code>https://mealie.example.com</code></td></tr><tr><td><code>MEALIE_API_TOKEN</code></td><td>Token from Settings → API Tokens; it acts as the user who created it.</td></tr></tbody></table><p>A missing credential is a warning, not a fatal error: the server still completes the MCP handshake and answers <code>tools/list</code>, and every actual call fails with setup instructions. A <strong>malformed</strong> <code>MEALIE_URL</code> exits immediately — that one could send the token to the wrong host. URLs with embedded credentials, a query string or a fragment are rejected for the same reason.</p><h2 id="optional-variables" tabindex="-1">Optional variables <a class="header-anchor" href="#optional-variables" aria-label="Permalink to “Optional variables”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>MEALIE_READ_ONLY</code></td><td>Exactly <code>true</code> registers the 17 read tools only</td></tr><tr><td><code>MEALIE_ACCEPT_LANGUAGE</code></td><td>e.g. <code>de-DE</code>; localises unit and label names</td></tr><tr><td><code>MEALIE_INSECURE_TLS</code></td><td>Exactly <code>true</code> accepts a self-signed certificate, scoped to this connection</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Booleans compare against the literal string <code>true</code></p><p><code>MEALIE_READ_ONLY=1</code>, <code>yes</code> or <code>True</code> all leave the flag <strong>off</strong>. A typo fails off, never on — check the startup line on stderr, which reports the mode in effect.</p></div><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p>Prefer <code>https://</code>. Using plain <code>http://</code> to a non-local host prints a warning: the API token would travel unencrypted.</p><p>If the instance uses a self-signed certificate, <code>MEALIE_INSECURE_TLS=true</code> disables certificate verification <strong>for this connection only</strong> — it does not touch <code>NODE_TLS_REJECT_UNAUTHORIZED</code> or affect any other TLS connection the process makes.</p><h2 id="localisation" tabindex="-1">Localisation <a class="header-anchor" href="#localisation" aria-label="Permalink to “Localisation”">​</a></h2><p><code>MEALIE_ACCEPT_LANGUAGE</code> (e.g. <code>de-DE</code>) is sent as the <code>accept-language</code> header, which Mealie honours on nearly every endpoint. It localises unit names, label names and validation messages. Unset, the choice is left to the server default.</p>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};